<style>
.atl-shell{background:#f8fafc;min-height:100vh}.atl-card{border:0;border-radius:18px;box-shadow:0 8px 28px rgba(15,23,42,.07)}.atl-hero{background:linear-gradient(120deg,#111827,#7f1d1d);color:#fff;border-radius:20px}.atl-stat{border:0;border-radius:16px;box-shadow:0 6px 20px rgba(15,23,42,.06)}.status-badge{display:inline-block;padding:.3rem .55rem;border-radius:20px;font-size:.72rem;font-weight:700}.s-present{background:#dcfce7;color:#166534}.s-absent{background:#fee2e2;color:#991b1b}.s-half_day{background:#fef3c7;color:#92400e}.s-on_leave{background:#dbeafe;color:#1e40af}.s-holiday{background:#f3e8ff;color:#6b21a8}.s-week_off{background:#e2e8f0;color:#334155}.s-unmarked{background:#fff;border:1px dashed #ef4444;color:#b91c1c}.attendance-table th,.attendance-table td{white-space:nowrap;vertical-align:middle}
